package com.gamehub.application.service; import com.gamehub.application.OperationsService; import java.time.Instant; import java.util.List; public final class ReservationService { private final OperationsService ops; public ReservationService(OperationsService ops){this.ops=ops;} public long reserve(long c,long s,Instant a,Instant b)throws Exception{if(a==null||b==null||!a.isBefore(b))throw new IllegalArgumentException("Invalid interval");return ops.reserve(c,s,a,b);} public void cancel(long c,long id)throws Exception{ops.cancelReservation(c,id);} public List<String> available(Instant a,Instant b)throws Exception{return ops.availableStations(a,b,null);} public List<String> mine(long c)throws Exception{return ops.reservations(c);} }